question.answer:
def distance2(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))

def affecter(points, centres):
    res = []
    for p in points:
        best, bd = 0, distance2(p, centres[0])
        for k in range(1, len(centres)):
            d = distance2(p, centres[k])
            if d < bd:
                bd, best = d, k
        res.append(best)
    return res

def recentrer(points, groupes, K, anciens):
    nouveaux = []
    for k in range(K):
        membres = [p for p, g in zip(points, groupes) if g == k]
        if not membres:
            nouveaux.append(anciens[k])
        else:
            d = len(membres[0])
            nouveaux.append(tuple(round(sum(m[i] for m in membres) / len(membres), 6)
                                  for i in range(d)))
    return nouveaux

def inertie(points, groupes, centres):
    return round(sum(distance2(p, centres[g]) for p, g in zip(points, groupes)), 4)

