question.answer:
from math import sqrt

def distance(a, b):
    return sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def silhouette(points, groupes):
    etiquettes = sorted(set(groupes))
    res = []
    for i, p in enumerate(points):
        memes = [q for j, q in enumerate(points) if groupes[j] == groupes[i] and j != i]
        if not memes:
            res.append(0.0)
            continue
        a = sum(distance(p, q) for q in memes) / len(memes)
        b = None
        for e in etiquettes:
            if e == groupes[i]:
                continue
            autres = [q for j, q in enumerate(points) if groupes[j] == e]
            if not autres:
                continue
            d = sum(distance(p, q) for q in autres) / len(autres)
            if b is None or d < b:
                b = d
        if b is None:
            res.append(0.0)
        else:
            res.append(round((b - a) / max(a, b), 4))
    return res

def silhouette_moyenne(points, groupes):
    s = silhouette(points, groupes)
    return round(sum(s) / len(s), 4) if s else 0.0
